int main(){ios::sync_with_stdio(false);cin.tie(nullptr);string line;while(getline(cin,line)){json input=json::parse(line);CwContext cw;auto cwArgument0=cw.tree(input.at("root"));auto cwArgument1=input.at("lo").get<int>();auto cwArgument2=input.at("hi").get<int>();cw.snapshot_inputs();auto result=Solution().solve(cwArgument0,cwArgument1,cwArgument2);cw.check_inputs();cout<<json(result).dump()<<"\n";}}
